80	interface ToolExecutionResult {
81	  clientMessages: OutgoingMessage[];
82	  suppressOutput: boolean;
83	}
84	export function createChatOrchestrator(
85	  provider: AIProvider,
86	  promptBuilder: PromptBuilder,
87	  toolRegistry?: ToolRegistry,
88	  options?: ChatOrchestratorOptions
89	): ChatOrchestrator {
90	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
91	  const contextConfig = createContextConfig(options?.contextConfig);
92	  const toolInstructions = toolRegistry?.getPromptInstructions();
93	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
94	  const tools = toolRegistry?.getDefinitions();
95	  const hooks = options?.hooks;
96	  const sessionStore = options?.sessionStore;
97	
98	  return {
99	    async processMessage(session: ChatSession): Promise<string> {
100	      return collectText(this.processMessageStream(session));
101	    },
102	
103	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
104	      try {
105	        if (hooks?.beforeSession) await hooks.beforeSession(session);
106	
107	        let userMessage = lastUserContent(session);
108	
109	        if (hooks?.beforeUserInput) {
110	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
111	        }
112	
113	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
114	
115	        const systemPrompt = hooks?.beforeModelResponse
116	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
117	          : baseSystemPrompt;
118	
119	        const messages: Message[] = toMessages(session.entries, contextConfig);
120	        let lastUsage: UsageMetadata | undefined;
121	        let responseText = '';
122	
123	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
124	        for (let round = 0; ; round++) {
125	          log.info('orchestrator', 'starting round', {round});
126	          const pendingToolCalls: ToolCall[] = [];
127	
128	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
129	          responseText += outcome.text;
130	          lastUsage = accumulateUsage(lastUsage, outcome.usage);
131	
132	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
133	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
134	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
135	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
136	            break;
137	          }
138	
139	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
140	          const {clientMessages, suppressOutput} = await executeToolCalls(
141	            pendingToolCalls,
142	            messages,
143	            session,
144	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
145	          );
146	          log.info('orchestrator', 'tool execution complete', {
147	            clientMessageCount: clientMessages.length,
148	            clientMessageTypes: clientMessages.map(m => m.type),
149	            suppressOutput,
150	          });
151	
152	          if (clientMessages.length > 0) {
153	            yield {type: 'tool_result' as const, clientMessages};
154	          }
155	
156	          if (suppressOutput) {
157	            yield {type: 'suppress_output' as const};
158	          }
159	        }
160	
161	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
162	      } catch (error) {
163	        if (hooks?.onError && error instanceof Error) {
164	          await hooks.onError(session, error);
165	        }
166	        throw error;
167	      } finally {
168	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
169	        commitStreamingEntries(session);
170	        try {
171	          if (hooks?.afterSession) await hooks.afterSession(session);
172	        } finally {
173	          await saveSession(sessionStore, session);
174	        }
175	      }
176	    },
177	  };
178	}
179	
180	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
181	function normalizeToolRounds(value: number | undefined): number {
182	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
183	  return Math.max(0, Math.floor(value));
184	}
185	
186	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
187	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
188	  if (round < maxToolRounds) return false;
189	  log.warn('orchestrator', 'tool budget exhausted', {
190	    maxToolRounds,
191	    requestedTools: pendingToolCalls.map(tc => tc.name),
192	  });
193	  return true;
194	}
195	
196	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
197	async function* closeExhaustedTurn(
198	  session: ChatSession,
199	  budget: ToolBudgetInfo,
200	  hook?: OnToolBudgetExhausted
201	): AsyncGenerator<MessageChunk, string> {
202	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
203	  if (sentence !== '') yield {type: 'text', text: sentence};
204	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
205	  return sentence;
206	}
207	
208	interface RoundOutcome {
209	  stopReason: string;
210	  text: string;
211	  usage?: UsageMetadata;
212	}
213	
214	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
215	async function* streamRound(
216	  provider: AIProvider,
217	  request: SendMessageParams,
218	  pendingToolCalls: ToolCall[]
219	): AsyncGenerator<MessageChunk, RoundOutcome> {
220	  let stopReason = '';
221	  let text = '';
222	  let usage: UsageMetadata | undefined;
223	
224	  for await (const chunk of provider.sendMessage(request)) {
225	    yield chunk;
226	    collectToolCalls(chunk, pendingToolCalls);
227	    stopReason = extractStopReason(chunk) ?? stopReason;
228	    usage = extractUsage(chunk) ?? usage;
229	    if (chunk.type === 'text') text += chunk.text;

